sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var metrics = {};

    var urlPatterns = [
        'api/now/table/cmdb_categories',
        'api/now/table/cmdb_ci',
        'api/now/table/cmdb_rel_type',
        'oauth_token.do'
    ];

    urlPatterns.forEach(function(pattern) {
        var count = 0;
        var totalResponseTime = 0;
        var totalSqlTime = 0;
        var totalBusinessRuleTime = 0;

        var logGr = new GlideRecord('syslog_transaction');
        logGr.addQuery('type', 'rest');
        logGr.addQuery('url', 'CONTAINS', pattern);
        logGr.query();

        while (logGr.next()) {
            count++;
            totalResponseTime += parseInt(logGr.getValue('response_time')) || 0;
            totalSqlTime += parseInt(logGr.getValue('sql_time')) || 0;
            totalBusinessRuleTime += parseInt(logGr.getValue('business_rule_time')) || 0;
        }

        metrics[pattern] = {
            call_count: count,
            avg_response_time: count > 0 ? totalResponseTime / count : 0,
            avg_sql_time: count > 0 ? totalSqlTime / count : 0,
            avg_business_rule_time: count > 0 ? totalBusinessRuleTime / count : 0
        };
    });

    return metrics;

})(request, response);
